#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    std::vector<std::vector<int>> minAbsDiff(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        int rows = m - k + 1, cols = n - k + 1;
        std::vector<std::vector<int>> ans(rows, std::vector<int>(cols, 0));

        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                std::vector<int> elems;
                for (int r = 0; r < k; ++r) {
                    for (int c = 0; c < k; ++c) {
                        elems.push_back(grid[i + r][j + c]);
                    }
                }
                std::sort(elems.begin(), elems.end());
                int min_diff = INT_MAX;
                bool found = false;
                for (size_t x = 1; x < elems.size(); ++x) {
                    if (elems[x] != elems[x - 1]) {
                        min_diff = std::min(min_diff, elems[x] - elems[x - 1]);
                        found = true;
                    }
                }
                ans[i][j] = found ? min_diff : 0;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[][] minAbsDiff(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int rows = m - k + 1, cols = n - k + 1;
        int[][] ans = new int[rows][cols];

        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                int[] elems = new int[k * k];
                int idx = 0;
                for (int r = 0; r < k; ++r) {
                    for (int c = 0; c < k; ++c) {
                        elems[idx++] = grid[i + r][j + c];
                    }
                }
                Arrays.sort(elems);
                int minDiff = Integer.MAX_VALUE;
                boolean found = false;
                for (int x = 1; x < elems.length; ++x) {
                    if (elems[x] != elems[x - 1]) {
                        minDiff = Math.min(minDiff, elems[x] - elems[x - 1]);
                        found = true;
                    }
                }
                ans[i][j] = found ? minDiff : 0;
            }
        }
        return ans;
    }
}

