var minAbsDiff = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const rows = m - k + 1, cols = n - k + 1;
    const ans = Array.from({ length: rows }, () => new Array(cols).fill(0));

    for (let i = 0; i < rows; ++i) {
        for (let j = 0; j < cols; ++j) {
            const elems = [];
            for (let r = 0; r < k; ++r) {
                for (let c = 0; c < k; ++c) {
                    elems.push(grid[i + r][j + c]);
                }
            }
            elems.sort((a, b) => a - b);
            let minDiff = Infinity;
            let found = false;
            for (let x = 1; x < elems.length; ++x) {
                if (elems[x] !== elems[x - 1]) {
                    minDiff = Math.min(minDiff, elems[x] - elems[x - 1]);
                    found = true;
                }
            }
            ans[i][j] = found ? minDiff : 0;
        }
    }
    return ans;
};
